contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address oracleParam) public {
        // The oracle must be a contract address (P reverts otherwise; keep domain admissible)
        vm.assume(oracleParam != address(0));
        vm.assume(oracleParam.code.length > 0);
        vm.assume(uint256(uint160(oracleParam)) < type(uint256).max / 2);

        IOracleProvider oracle_ = IOracleProvider(oracleParam);

        PayoffDefinition memory pd;
        pd.payoffDefinition = bytes30(0);

        IProduct.ProductInfo memory info;
        info.name = "t";
        info.symbol = "T";
        info.oracle = oracle_;
        info.maintenance = UFixed18.wrap(1e18);
        info.fundingFee = UFixed18.wrap(1e17);
        info.makerFee = UFixed18.wrap(1e17);
        info.takerFee = UFixed18.wrap(1e17);
        info.positionFee = UFixed18.wrap(1e17);
        info.makerLimit = UFixed18.wrap(1e24);
        info.utilizationCurve = JumpRateUtilizationCurve({
            minRate: PackedFixed18.wrap(0),
            maxRate: PackedFixed18.wrap(1e18),
            targetRate: PackedFixed18.wrap(5e17),
            targetUtilization: PackedUFixed18.wrap(8e17)
        });

        try c.initialize(info) {
            // General rule: oracle() returns the oracle address the product was initialized with.
            assertTrue(
                IOracleProvider(address(c.oracle())) == oracle_,
                "oracle() must return the configured oracle address"
            );
        } catch {
            // Initialization must succeed for admissible inputs.
            assertTrue(false, "initialize reverted on admissible input");
        }
    }
}

