// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Factory factory;
    FakeOracle oracle;

    function setUp() public {
        factory = new Factory();
        oracle = new FakeOracle();
    }

    function testFuzz_property(uint256 version, uint256 rawPrice) public {
        vm.assume(version != 0);
        uint256 price = bound(rawPrice, 0, uint256(type(int256).max));

        // initialize c through a contract factory (initialize requires a contract caller)
        IOracleProvider.OracleVersion memory ov =
            IOracleProvider.OracleVersion({version: version, timestamp: 1, price: Fixed18.wrap(int256(price))});
        oracle.set(ov);

        IProduct.ProductInfo memory info;
        info.name = "T";
        info.symbol = "T";
        info.payoffDefinition = PayoffDefinition({
            payoffType: PayoffDefinitionLib.PayoffType(1),
            payoffDirection: PayoffDefinitionLib.PayoffDirection(1),
            data: bytes30(0)
        });
        info.oracle = oracle;
        info.maintenance = UFixed18.wrap(1e18);
        info.fundingFee = UFixed18.wrap(0);
        info.makerFee = UFixed18.wrap(0);
        info.takerFee = UFixed18.wrap(0);
        info.positionFee = UFixed18.wrap(0);
        info.makerLimit = UFixed18.wrap(1e30);
        info.utilizationCurve = JumpRateUtilizationCurve({
            minRate: PackedFixed18.wrap(0),
            maxRate: PackedFixed18.wrap(0),
            targetRate: PackedFixed18.wrap(0),
            targetUtilization: PackedUFixed18.wrap(0)
        });

        c = factory.deployC(info);

        // General rule: the product's delegating view atVersion(v) must successfully
        // serve oracle data through the configured oracle for ANY version.
        bool ok;
        try c.atVersion(version) returns (IOracleProvider.OracleVersion memory res) {
            ok = res.version == version && Fixed18.unwrap(res.price) == int256(price);
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

contract Factory {
    function deployC(IProduct.ProductInfo memory info) external returns (C c) {
        c = new C();
        c.initialize(info);
    }
}

contract FakeOracle is IOracleProvider {
    OracleVersion private _current;

    function set(OracleVersion memory v) external { _current = v; }

    function sync() external view returns (OracleVersion memory) { return _current; }
    function currentVersion() external view returns (OracleVersion memory) { return _current; }
    function atVersion(uint256) external view returns (OracleVersion memory) { return _current; }
}

