pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));

        // Adversarial environment: a contract-backed harness and oracle stub.
        // Reference stores the validated contract oracle address; the bug
        // returns address(0) instead of it for every caller.
        Harness h = new Harness();
        OracleStub oracleStub = new OracleStub();
        h.init(address(c), address(oracleStub));

        vm.prank(actor);
        IOracleProvider returned = c.oracle();

        // General rule: for every admissible caller, oracle() returns a live
        // contract address (non-zero and carrying code) — never address(0).
        assertTrue(
            address(returned) != address(0) && address(returned).code.length > 0,
            "oracle() must return the stored live oracle contract, not the zero address"
        );
    }
}

contract OracleStub {
    // Minimal contract whose only role is being a valid code-carrying oracle address.
}

interface IProductCopy {
    struct PayoffDefCopy {
        uint8 payoffType;
        uint8 payoffDirection;
        bytes30 data;
    }
    struct CurveCopy {
        int128 minRate;
        int128 maxRate;
        int128 targetRate;
        uint128 targetUtilization;
    }
    struct ProductInfoCopy {
        string name;
        string symbol;
        PayoffDefCopy payoffDefinition;
        address oracle;
        uint256 maintenance;
        uint256 fundingFee;
        uint256 makerFee;
        uint256 takerFee;
        uint256 positionFee;
        uint256 makerLimit;
        CurveCopy utilizationCurve;
    }

    function initialize(ProductInfoCopy calldata productInfo_) external;
}

contract Harness {
    function init(address product, address oracle) external {
        IProductCopy.PayoffDefCopy memory pd = IProductCopy.PayoffDefCopy({
            payoffType: 0, // Linear (valid default payoff)
            payoffDirection: 2,
            data: bytes30(0)
        });
        IProductCopy.CurveCopy memory curve = IProductCopy.CurveCopy({
            minRate: int128(0),
            maxRate: int128(1e18),
            targetRate: int128(5e17),
            targetUtilization: uint128(8e17)
        });
        IProductCopy.ProductInfoCopy memory info = IProductCopy.ProductInfoCopy({
            name: "T",
            symbol: "T",
            payoffDefinition: pd,
            oracle: oracle,
            maintenance: 0,
            fundingFee: 0,
            makerFee: 0,
            takerFee: 0,
            positionFee: 0,
            makerLimit: 0,
            utilizationCurve: curve
        });
        IProductCopy(product).initialize(info);
    }
}

