pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 which) public {
        // Two freshly deployed oracle stubs: both are valid admissible contract addresses.
        // The fuzzer picks which one gets configured on c.
        OracleStub a = new OracleStub();
        OracleStub b = new OracleStub();
        OracleStub chosen = which % 2 == 0 ? a : b;

        // Build calldata for c.initialize(ProductInfo) manually (struct types from C's
        // source are not importable here). ProductInfo =
        // (string name, string symbol, (uint8 payoffType, uint8 payoffDirection, bytes30 data),
        //  address oracle, uint256 maintenance, uint256 fundingFee, uint256 makerFee,
        //  uint256 takerFee, uint256 positionFee, uint256 makerLimit,
        //  (int128,int128,int128,uint128) utilizationCurve)
        // Head is 16 words: nameOff, symOff, payoffDef(3 inline), oracle, 6 params, curve(4 inline).
        // Tail: two empty-string length words. Valid payoff: type 0 (Linear), direction 0, data 0.
        // All fees / params zero, makerLimit zero.
        bytes memory head = abi.encode(
            uint256(0x240),                 // 0: offset of name
            uint256(0x260),                 // 1: offset of symbol
            uint256(0),                     // 2: payoffType (Linear)
            uint256(0),                     // 3: payoffDirection (Linear)
            uint256(0),                     // 4: data
            uint256(uint160(address(chosen))), // 5: oracle address
            uint256(0),                     // 6: maintenance
            uint256(0),                     // 7: fundingFee
            uint256(0),                     // 8: makerFee
            uint256(0),                     // 9: takerFee
            uint256(0),                     // 10: positionFee
            uint256(0),                     // 11: makerLimit
            uint256(0),                     // 12: curve.minRate
            uint256(0),                     // 13: curve.maxRate
            uint256(0),                     // 14: curve.targetRate
            uint256(0)                      // 15: curve.targetUtilization
        );
        bytes memory tail = abi.encode(uint256(0), uint256(0));
        bytes memory cd = bytes.concat(C.initialize.selector, head, tail);

        // The test contract itself has code, satisfying the controller-is-contract check.
        (bool ok, ) = address(c).call(cd);
        ok; // initialization result does not affect the property's generality

        // General rule: for every admissible configured oracle contract address O,
        // c.oracle() returns exactly O.
        assertTrue(address(c.oracle()) == address(chosen));
    }
}

