contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 seed) public {
        // Deploy an oracle stub with code; the fuzzer's `seed` keeps the input space open.
        OracleStub oracleStub = new OracleStub();
        seed;

        // initialize(ProductInfo): name, symbol, PayoffDefinition(type, direction, data),
        // oracle, maintenance, fundingFee, makerFee, takerFee, positionFee, makerLimit, curve
        bytes memory initCalldata = abi.encodeWithSelector(
            C.initialize.selector,
            "product",
            "PRD",
            uint8(1),
            uint8(1),
            bytes30(uint240(1e18)),
            address(oracleStub),
            uint256(1e18),
            uint256(0),
            uint256(0),
            uint256(0),
            uint256(0),
