            int128(0),
            int128(1e18),
            int128(5e17),
            uint128(5e17)
        );

        (bool initOk, ) = address(c).call(initCalldata);
        vm.assume(initOk); // admissible domain: initialization succeeded

        // General rule: the configured oracle getter must expose the live oracle
        // contract (non-zero, with code). Mutant returns address(0) always.
        assertTrue(
            c.oracle() != address(0) && c.oracle().code.length > 0,
            "oracle getter must return the configured oracle contract"
        );
