pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    MockController controller;

    struct PayoffDefT { uint8 payoffType; uint8 payoffDirection; bytes30 data; }
    struct CurveT { int128 minRate; int128 maxRate; int128 targetRate; uint128 targetUtilization; }
    struct InfoT {
        string name;
        string symbol;
        PayoffDefT pd;
        address oracle;
        uint256 maintenance;
        uint256 fundingFee;
        uint256 makerFee;
        uint256 takerFee;
        uint256 positionFee;
        uint256 makerLimit;
        CurveT curve;
    }

    function setUp() public {
        controller = new MockController();
        c = new C();
    }

    function testFuzz_property(address newOracle) public {
        // The oracle must be a contract address (isContract check in _updateOracle).
        vm.assume(newOracle.code.length > 0);

        // Initialize the product from the mock controller (msg.sender must be a contract).
        InfoT memory info;
        info.pd = PayoffDefT({payoffType: 0, payoffDirection: 0, data: bytes30(0)});
        info.oracle = address(controller);
        (bool initOk, ) = address(c).call(
            abi.encodeWithSignature(
                "initialize((string,string,(uint8,uint8,bytes30),address,uint256,uint256,uint256,uint256,uint256,uint256,(int128,int128,int128,uint128)))",
                info
            )
        );
        assertTrue(initOk, "initialize must succeed");

        // Product owner (mock controller resolves coordinator 0 owner = this contract) updates the oracle.
        (bool updOk, ) = address(c).call(abi.encodeWithSignature("updateOracle(address)", newOracle));
        assertTrue(updOk, "updateOracle must succeed for a contract address");

        // General rule: oracle() returns EXACTLY the stored oracle address.
        assertTrue(address(c.oracle()) == newOracle, "oracle() must return the stored oracle address");
    }
}

contract MockController {
    function isProduct(address) external pure returns (bool) { return true; }
    function coordinatorFor(address) external pure returns (uint256) { return 0; }
    function owner(uint256) external view returns (address) { return msg.sender; }
    function minFundingFee() external pure returns (uint256) { return 0; }
    function incentivizer() external pure returns (address) { return address(0); }
    function collateral() external pure returns (address) { return address(0); }
    function paused() external pure returns (bool) { return false; }
}
